    'chunk_6cff0087a54b',
    'converted_sql-sql-server-ver17.md',
    57319,
    '### XML

For a specific product model, the query retrieves the first two feature descriptions from the
<Features > element in the product model catalog.
                { string($s) }  
              </Tool>  
          }  
        </Tools>  
        <Materials>  
            { for $s in (//AWMI:root/AWMI:Location)[1]//AWMI:step//AWMI:material  
              return  
                 <Material>  
                    { string($s) }  
                 </Material>  
             }  
         </Materials>  
  </Location>  
'') as Result  
